class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        for j in range(n + 1):
            dp[0][j] = 1
        for i in range(1, n + 1):
            for j in range(i + 1):
                if s[i - 1] == 'I':
                    dp[i][j] = sum(dp[i - 1][k] for k in range(j)) % MOD
                else:
                    dp[i][j] = sum(dp[i - 1][k] for k in range(j, i)) % MOD
        return sum(dp[n]) % MOD

