public:
    int numPermsDISequence(string s) {
        const int MOD = 1e9 + 7;
        int n = s.size();
        vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
        for (int j = 0; j <= n; j++) dp[0][j] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                long long sum = 0;
                if (s[i - 1] == 'I') {
                    for (int k = 0; k < j; k++) sum += dp[i - 1][k];
                } else {
                    for (int k = j; k < i; k++) sum += dp[i - 1][k];
                }
                dp[i][j] = sum % MOD;
            }
        }
        long long ans = 0;
        for (int j = 0; j <= n; j++) ans += dp[n][j];
        return ans % MOD;
    }
};

