class Solution {
public:
    int numPermsDISequence(string s) {
        const int MOD = 1e9 + 7;
        int n = s.size();
        vector<long long> prev(n + 1, 1);
        for (int i = 1; i <= n; i++) {
            vector<long long> cur(n + 1, 0);
            long long run = 0;
            if (s[i - 1] == 'I') {
                for (int j = 1; j <= i; j++) {
                    run += prev[j - 1];
                    cur[j] = run % MOD;
                }
            } else {
                for (int j = i - 1; j >= 0; j--) {
                    run += prev[j];
                    cur[j] = run % MOD;
                }
            }
            prev = cur;
        }
        long long ans = 0;
        for (long long v : prev) ans += v;
        return ans % MOD;
    }
};

